// ---- static_asserts: schema tied to the decompile ----
static_assert(kTotalSlots == 255, "param slot count must be 255");
static_assert(kNamedParams == 98, "named param count must match params.json");
static_assert(kIdToIndex[0] == 0, "id 0 (osc1 shape) maps to its slot");
static_assert(kIdToIndex[14] == 14, "id 14 (filter type) maps to its slot");
static_assert(kIdToIndex[38] == 38, "id 38 (play mode type) maps to its slot");
static_assert(kIdToIndex[91] == 91, "id 91 (osc phase shift) maps to its slot");
static_assert(kIdToIndex[92] == 92, "id 92 (unison phase shi) maps to its slot");
static_assert(kIdToIndex[254] == -1, "id 254 (0xfe, master volume) is a common-setting, outside the 98 named rows (spec_mastervol.md)");
static_assert(254 < kTotalSlots, "0xfe is within the 255-slot space");
static_assert(kNamedParamsTab[14].uniform_step && !kNamedParamsTab[14].bipolar, "filter type (id 14) is a 5-position discrete (spec_filter.md §1)");

// ---- constexpr lookup helpers ----
// id -> named param (nullptr if the slot is unnamed).
inline constexpr const NamedParam* by_id(std::uint32_t id) {
  if (id >= kTotalSlots) return nullptr;
  int i = kIdToIndex[id];
  return i < 0 ? nullptr : &kNamedParamsTab[i];
}

// name-key -> id (returns 0xFFFFFFFu if not found).
inline constexpr std::uint32_t id_from_key(const char* key) {
  std::size_t lo = 0, hi = kNameKeyCount;
  while (lo < hi) {
    std::size_t mid = lo + (hi - lo) / 2;
    // manual strcmp for constexpr
    const char* a = kNameKeys[mid].key; const char* b = key;
    int c = 0;
    while (*a && *b && *a == *b) { ++a; ++b; }
    c = static_cast<int>(*a) - static_cast<int>(*b);
    if (c < 0) lo = mid + 1; else if (c > 0) hi = mid;
    else return kNameKeys[mid].id;
  }
  return 0xFFFFFFFu;
}

